// Tiny router: handle({ method, path, body }) -> { status, body }.
function createApi(store) {
  return function handle({ method, path, body = {} }) {
    const stockMatch = path.match(/^\/stock\/([^/]+)$/);
    if (method === 'GET' && stockMatch) {
      const sku = decodeURIComponent(stockMatch[1]);
      return { status: 200, body: { sku, stock: store.getStock(sku) } };
    }
    if (method === 'POST' && path === '/stock') {
      try {
        store.addItem(body.sku, body.qty);
        return { status: 201, body: { sku: body.sku, stock: store.getStock(body.sku) } };
      } catch (e) {
        return { status: 400, body: { error: e.message } };
      }
    }
    return { status: 404, body: { error: 'NOT_FOUND' } };
  };
}

module.exports = { createApi };
// In-memory inventory. `clock` is injectable so tests can control time.
function createStore({ clock = Date.now } = {}) {
  const stock = new Map();

  function assertQty(qty) {
    if (!Number.isInteger(qty) || qty <= 0) throw new Error('INVALID_QTY');
  }

  return {
    clock,
    addItem(sku, qty) {
      assertQty(qty);
      stock.set(sku, (stock.get(sku) || 0) + qty);
    },
    removeItem(sku, qty) {
      assertQty(qty);
      const current = stock.get(sku) || 0;
      if (qty > current) throw new Error('INSUFFICIENT_STOCK');
      stock.set(sku, current - qty);
    },
    getStock(sku) {
      return stock.get(sku) || 0;
    },
  };
}

module.exports = { createStore };
